const express = require('express');
const session = require('express-session');
const app = express();

app.use(express.json());
app.use(session({
  secret: 'enterprise-super-secret',
  resave: false,
  saveUninitialized: false,
  cookie: { secure: true, httpOnly: true, sameSite: 'strict', maxAge: 3600000 }
}));

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;

  if (validateCredentials(username, password)) {
    // DEFENSE AGAINST SESSION FIXATION:
    // Immediately regenerate session identifier upon authentication privilege change!
    req.session.regenerate((err) => {
      if (err) return res.status(500).json({ error: 'Session error' });

      req.session.userId = username;
      req.session.authenticated = true;

      res.json({ message: 'Login successful with fresh session ID' });
    });
  } else {
    res.status(401).json({ error: 'Invalid credentials' });
  }
});

app.post('/api/auth/token', (req, res) => {
  const authToken = generateSecureToken();

  res.cookie('auth_session', authToken, {
    httpOnly: true, // Prevents client-side JS (document.cookie) from accessing the cookie; blocks XSS theft
    secure: true,   // Ensures cookie is strictly transmitted over encrypted HTTPS connections; prevents cleartext sniffing
    sameSite: 'strict', // Blocks cross-site transmission during external navigation; mitigates CSRF
    maxAge: 24 * 60 * 60 * 1000, // 24 hours expiration
    path: '/'       // Restrict path scope
  });

  res.json({ message: 'Authenticated successfully' });
});

const crypto = require('crypto');

function generateTOTP(secretBase32, timeStepSeconds = 30) {
  // 1. Calculate time counter step T = floor(current_unix_time / timeStepSeconds)
  const epoch = Math.floor(Date.now() / 1000);
  const counter = Math.floor(epoch / timeStepSeconds);

  // Convert counter integer to 8-byte buffer
  const counterBuffer = Buffer.alloc(8);
  counterBuffer.writeBigInt64BE(BigInt(counter));

  // 2. Compute HMAC-SHA1 of counter with shared secret
  const hmac = crypto.createHmac('sha1', Buffer.from(secretBase32, 'utf-8'));
  hmac.update(counterBuffer);
  const hash = hmac.digest();

  // 3. Dynamic Truncation: extract 4 bytes from offset determined by last nibble
  const offset = hash[hash.length - 1] & 0x0f;
  const binary = ((hash[offset] & 0x7f) << 24) |
                 ((hash[offset + 1] & 0xff) << 16) |
                 ((hash[offset + 2] & 0xff) << 8) |
                 (hash[offset + 3] & 0xff);

  // 4. Generate 6-digit code via modulo 1,000,000
  const code = (binary % 1000000).toString().padStart(6, '0');
  return code;
}

